<template>
    <div class="image-compare" ref="containerRef">
        <!-- 底层图片 (before) -->
        <div class="image-compare__before">
            <l-img 
                :src="beforeImage" 
                w="100%" 
                h="100%" 
                :draggable="false"
                radius="8px"
            />
        </div>
        
        <!-- 顶层图片 (after) -->
        <div 
            class="image-compare__after" 
            :style="{ clipPath: `inset(0 calc(100% - ${splitPosition}%) 0 0)` }"
        >
            <l-img 
                :src="afterImage" 
                w="100%" 
                h="100%" 
                :draggable="false"
                radius="8px"
            />
        </div>
        
        <!-- 分割线和拖拽手柄 -->
        <div 
            class="image-compare__divider"
            :style="{ left: `${splitPosition}%` }"
            @mousedown="clickStartDrag"
        >
            <div class="image-compare__handle">
                <l-img src="/static/images/arrow-left.png" w="18px" h="18px" />
                <l-img src="/static/images/arrow-right.png" w="18px" h="18px" />
            </div>
        </div>
    </div>
</template>

<script setup>
    import { ref, onMounted, onUnmounted } from 'vue';
    import LImg from '@/components/l-img.vue';

    // Props定义
    const props = defineProps({
        beforeImage: {
            type: String,
            required: true
        },
        afterImage: {
            type: String,
            required: true
        },
        initialPosition: {
            type: Number,
            default: 50,
            validator: (value) => value >= 0 && value <= 100
        }
    });

    // Emits定义
    const emit = defineEmits(['position-change']);

    // 响应式数据
    const containerRef = ref(null);
    const splitPosition = ref(props.initialPosition);
    const isDragging = ref(false);

    // 开始拖拽
    const clickStartDrag = (event) => {
        event.preventDefault();
        isDragging.value = true;
        
        // 在组件容器上监听鼠标事件
        if (containerRef.value) {
            containerRef.value.addEventListener('mousemove', clickMoveDrag);
            containerRef.value.addEventListener('mouseleave', clickEndDrag);
            containerRef.value.addEventListener('mouseup', clickEndDrag);
        }
        
        // 改变光标样式，但只在组件内
        containerRef.value.style.cursor = 'col-resize';
        containerRef.value.style.userSelect = 'none';
    };

    // 拖拽中
    const clickMoveDrag = (event) => {
        if (!isDragging.value || !containerRef.value) return;
        
        const containerRect = containerRef.value.getBoundingClientRect();
        const newPosition = ((event.clientX - containerRect.left) / containerRect.width) * 100;
        
        // 边界限制
        splitPosition.value = Math.max(0, Math.min(100, newPosition));
        
        // 触发位置变化事件
        emit('position-change', splitPosition.value);
    };

    // 结束拖拽
    const clickEndDrag = () => {
        if (!isDragging.value) return;
        
        isDragging.value = false;
        
        // 移除组件容器上的事件监听器
        if (containerRef.value) {
            containerRef.value.removeEventListener('mousemove', clickMoveDrag);
            containerRef.value.removeEventListener('mouseleave', clickEndDrag);
            containerRef.value.removeEventListener('mouseup', clickEndDrag);
            
            // 恢复光标样式
            containerRef.value.style.cursor = '';
            containerRef.value.style.userSelect = '';
        }
    };

    // 清理事件监听器
    onUnmounted(() => {
        if (containerRef.value) {
            containerRef.value.removeEventListener('mousemove', clickMoveDrag);
            containerRef.value.removeEventListener('mouseleave', clickEndDrag);
            containerRef.value.removeEventListener('mouseup', clickEndDrag);
        }
    });
</script>

<style scoped lang="scss">
    .image-compare {
        width: 100%;
        height: 100%;
        position: relative;
        overflow: hidden;
        cursor: default;
    }

    .image-compare__before,
    .image-compare__after {
        position: absolute;
        top: 0;
        left: 0;
        width: 100%;
        height: 100%;
    }

    .image-compare__before {
        z-index: 1;
    }

    .image-compare__after {
        z-index: 2;
        transition: clip-path 0.1s ease-out;
    }

    .image-compare__divider {
        position: absolute;
        top: 0;
