        transform: translate(-50%, -50%);
        width: 52px;
        height: 52px;
        background-color: var(--bg-secondary);
        border-radius: 50%;
        display: flex;
        align-items: center;
        justify-content: center;
        cursor: col-resize;
        box-shadow: 0 2px 8px rgba(0, 0, 0, 0.15);
        
        // &:hover {
        //     background-color: var(--tool-session-item-hover);
        // }
    }

    .image-compare__handle-icon {
        font-size: 14px;
